 "content": "def transform(grid):
    n, m = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # All cells on a diagonal share the same color; infer the diagonal palette
    # from colored cells, extending the repeating diagonal sequence.
    diagonal = {}
    for r in range(n):
        for c in range(m):
            if grid[r][c]:
                diagonal[c-r] = grid[r][c]
    if not diagonal:
        return out
    offsets = sorted(diagonal)
    period = 1
    for p in range(1, n+m):
        if all(diagonal[a] == diagonal[b] for a in offsets for b in offsets
               if (a-b) % p == 0):
            period = p
            break
    # Build an offset-to-color lookup, using known congruent offsets where possible.
    for r in range(n):
        for c in range(m):
            d = c-r
            if out[r][c] == 0:
                matches = [v for k,v in diagonal.items() if (d-k) % period == 0]
                if matches:
                    out[r][c] = matches[0]
    return out

